package com.jnapanam.sportszone.membership.controller; import com.jnapanam.sportszone.membership.dto.*; import com.jnapanam.sportszone.membership.service.MembershipService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/memberships") public class CustomerMembershipController{private final MembershipService service;public CustomerMembershipController(MembershipService s){service=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public CustomerMembershipResponse subscribe(Authentication a,@Valid @RequestBody SubscribeRequest r){return service.subscribe(id(a),r);}@GetMapping("/me") public List<CustomerMembershipResponse> mine(Authentication a){return service.mine(id(a));}@PostMapping("/{membershipId}/cancel") public CustomerMembershipResponse cancel(Authentication a,@PathVariable UUID membershipId){return service.cancel(id(a),membershipId);}private static UUID id(Authentication a){return UUID.fromString(a.getName());}}
